namespace Scada.Api.Runtime;

public static partial class ContextualHelpCatalog
{
    private static ContextualHelpField IF(string locale, string key, string pl, string el, string sl, string pd, string ed, string sd, string pe, string ee, string se) =>
        new(key, Pick(locale, pl, el, sl), Pick(locale, pd, ed, sd), Pick(locale, pe, ee, se), "");

    private static IEnumerable<ContextualHelpTopic> BuildIntelligenceLearningGuides(string locale)
    {
        yield return LT(locale, "intelligence.profiles-equipment", "intelligence",
            Tx("Inteligência: perfis de sinais e equipamentos", "Intelligence: signal profiles and Equipment", "Inteligencia: perfiles de señales y equipos"),
            Tx("Reúna os TAGs de uma máquina em um perfil e diga a qual equipamento esse perfil pertence.", "Gather a machine's TAGs in a profile and specify which Equipment uses it.", "Reúna TAGs de una máquina en un perfil e indique a qué equipo pertenece."),
            [
                LS(locale, "Comece com um equipamento conhecido", "Start with familiar Equipment", "Empiece por un equipo conocido",
                    "Para uma bomba, você pode ter corrente, velocidade, vazão e pressão. Não precisa inventar um sensor de vibração se ele não existe. Crie um perfil com os sinais disponíveis e relevantes; marque como obrigatórios aqueles sem os quais a comparação pretendida não faz sentido. Uma análise futura ainda pode exigir entradas específicas que seu perfil não oferece.",
                    "For a pump you might have current, speed, flow and pressure. Do not invent a vibration sensor that is absent. Build a profile from relevant available signals and mark as required those without which the intended comparison is meaningless. A particular analysis can still require inputs your profile does not provide.",
                    "Para una bomba puede disponer de corriente, velocidad, caudal y presión. No invente un sensor de vibración ausente. Cree un perfil con señales disponibles y relevantes; marque obligatorias las necesarias para la comparación. Un análisis particular puede exigir entradas que el perfil no ofrece."),
                new ContextualHelpSection(Pick(locale, "O que preencher no perfil", "What to fill in the profile", "Qué completar en el perfil"), Pick(locale,
                    "Pense no perfil como uma ficha de medições. Ele explica quais sinais serão usados e o que cada um representa. A associação liga essa ficha ao equipamento cadastrado, como Bomba 01.\n\nUse os seletores para escolher equipamento e TAGs. O SCADIVO mantém as referências internas e cria os códigos técnicos automaticamente; não é preciso digitar GUIDs nem inventar chaves. A tabela mostra o que você precisa preencher.",
                    "Think of the profile as a measurement sheet. It describes which signals will be used and what each one represents. The assignment connects that sheet to registered Equipment, such as Pump 01.\n\nUse pickers to choose Equipment and TAGs. SCADIVO keeps internal references and creates technical keys automatically; you do not need to type GUIDs or invent codes. The table shows what you need to fill in.",
                    "Piense en el perfil como una ficha de mediciones. Describe qué señales se usarán y qué representa cada una. La asociación vincula esa ficha al equipo registrado, como Bomba 01.\n\nUse los selectores para elegir equipo y TAGs. SCADIVO conserva las referencias internas y crea las claves técnicas automáticamente; no necesita escribir GUIDs ni inventar códigos. La tabla indica qué debe completar."), Fields:
                [
                    IF(locale, "profile.name", "Nome de exibição", "Display name", "Nombre visible", "Título compreensível para quem configura e consulta.", "A recognizable title for authors and readers.", "Título comprensible para quien configura y consulta.", "Bomba de recalque", "Discharge pump", "Bomba de impulsión"),
                    IF(locale, "signal.tag", "Referência de TAG", "TAG reference", "Referencia TAG", "Escolha o TAG existente que contém a medição. Confira tipo, caminho e unidade apresentados.", "Choose the existing measurement TAG. Check its displayed type, path and unit.", "Elija el TAG de medición existente. Compruebe tipo, ruta y unidad mostrados.", "Bomba 01 · Corrente · A", "Pump 01 · Current · A", "Bomba 01 · Corriente · A"),
                    IF(locale, "signal.required", "Obrigatório ou opcional", "Required or optional", "Obligatorio u opcional", "Obrigatório indica que o sinal é necessário para o perfil. Opcional permite registrar que uma medição pode estar ausente; não garante que toda análise consiga funcionar sem ela.", "Required means the signal is needed for this profile. Optional allows a measurement to be absent; it does not guarantee every analysis works without it.", "Obligatorio indica que la señal es necesaria. Opcional permite ausencia, pero no garantiza que todo análisis funcione sin ella.", "Corrente obrigatória; vibração opcional", "Current required; vibration optional", "Corriente obligatoria; vibración opcional"),
                    IF(locale, "signal.role", "O que esta medição representa?", "What does this measurement represent?", "¿Qué representa esta medición?", "Escreva um nome fácil de reconhecer, como corrente do motor. No campo Significado da medição, escolha uma opção quando quiser habilitar análises compatíveis. Essa escolha não converte unidades nem deduz dados que o instrumento não fornece.", "Enter a recognizable name, such as motor current. In Measurement meaning, choose an option when you want to enable compatible analyses. This choice does not convert units or infer data the instrument does not provide.", "Escriba un nombre fácil de reconocer, como corriente del motor. En Significado de la medición, elija una opción para habilitar análisis compatibles. La elección no convierte unidades ni infiere datos que el instrumento no proporciona.", "Corrente elétrica do motor", "Motor current", "Corriente eléctrica del motor"),
                    IF(locale, "assignment", "Associação de equipamento", "Equipment assignment", "Asignación de equipo", "Liga o perfil ao equipamento cadastrado. Um equipamento pode usar mais de um perfil; escolha o nome correto antes de analisar.", "Links the profile to registered Equipment. Equipment can use more than one profile; choose the right name before analysis.", "Vincula el perfil al equipo registrado. Un equipo puede usar varios perfiles; elija el nombre correcto antes del análisis.", "Bomba 01 → Perfil da bomba de recalque", "Pump 01 → discharge pump profile", "Bomba 01 → perfil de la bomba de impulsión")
                ]),
                LS(locale, "Salvar, habilitar e ativar são passos diferentes", "Saving, enabling and activation differ", "Guardar, habilitar y activar son pasos distintos",
                    "Salve perfis e associações no Working, o rascunho do projeto. Selecione os equipamentos ou locais elegíveis e publique a revisão antes de ativar o escopo, isto é, o recurso escolhido para análise. A licença permite o uso, mas você decide onde ativá-lo. Salvar e ativar não fazem uma consulta automaticamente.\n\nPara configurar, a conta precisa de EngineeringModify e concessão explícita AssetProcessIntelligenceManage, global ou para o recurso. O papel developer inicial já inclui essa concessão, mas um administrador pode alterá-la. Confira a permissão efetiva; o nome do papel não basta.",
                    "Save profiles and assignments in Working, the project draft. Select eligible equipment or locations and publish the revision before activating the scope, meaning the resource selected for analysis. The license allows use, but you decide where to activate it. Saving and activating do not automatically run a query.\n\nConfiguration requires EngineeringModify and an explicit AssetProcessIntelligenceManage grant, global or for the resource. The initial developer role includes that grant, but an administrator can change it. Check effective permission; the role name is not enough.",
                    "Guarde perfiles y asociaciones en Working, el borrador del proyecto. Seleccione equipos o lugares elegibles y publique la revisión antes de activar el alcance, es decir, el recurso elegido para análisis. La licencia permite el uso, pero usted decide dónde activarlo. Guardar y activar no hacen una consulta automáticamente.\n\nConfigurar requiere EngineeringModify y concesión explícita AssetProcessIntelligenceManage, global o para el recurso. El rol developer inicial la incluye, pero un administrador puede cambiarla. Compruebe el permiso efectivo; no basta el nombre del rol.")
            ], "intelligence.overview", "intelligence.operating-contexts", "intelligence.dashboard-workflow", "tags.overview", "security.users-roles-capabilities");

        yield return LT(locale, "intelligence.operating-contexts", "intelligence",
            Tx("Inteligência: contexto operacional e etapas", "Intelligence: operating context and stages", "Inteligencia: contexto operativo y etapas"),
            Tx("Descreva em que condição comparar um equipamento e como agrupá-lo no processo.", "Describe the conditions for comparing Equipment and how it belongs to the process.", "Describa condiciones para comparar un equipo y cómo se agrupa en el proceso."),
            [
                LS(locale, "Compare condições que tenham sentido", "Compare meaningful conditions", "Compare condiciones con sentido",
                    "Corrente maior pode ser esperada se velocidade ou carga aumentou. Um contexto operacional explicita condições, como bomba ligada e velocidade em uma faixa definida, para selecionar evidências comparáveis. Ele não aprende automaticamente o modo de operação nem transforma correlação em diagnóstico. Defina limites com conhecimento do equipamento.",
                    "Higher current may be expected when speed or load rises. An operating context states conditions, such as pump running and speed within a defined range, to select comparable evidence. It does not automatically learn operating mode or turn correlation into diagnosis. Choose limits using Equipment knowledge.",
                    "Mayor corriente puede ser esperable si aumenta velocidad o carga. El contexto explicita condiciones, como bomba en marcha y velocidad dentro de un intervalo, para seleccionar evidencia comparable. No aprende automáticamente el modo ni convierte correlación en diagnóstico. Defina límites con conocimiento del equipo."),
                LS(locale, "Preencha o contexto", "Fill in the context", "Complete el contexto",
                    "Escolha a associação do equipamento e dê ao contexto um nome que explique a condição, como Bomba ligada em vazão normal. Adicione ao menos uma condição conferida em um TAG do perfil. A chave técnica é criada automaticamente.\n\nPara valores numéricos, o intervalo inclui mínimo e máximo e usa a unidade atual do TAG. Para booleanos, escolha Verdadeiro ou Falso. Para String ou Enum, use o valor exato, inclusive maiúsculas quando aplicável.\n\nAs leituras precisam ter o mesmo horário UTC de origem. Leituras apenas próximas no tempo não bastam. Se o contexto mudar em outra edição, atualize a tela e confira suas condições antes de salvar.",
                    "Choose the equipment assignment and give the context a name explaining the condition, such as Pump running at normal flow. Add at least one condition checked against a TAG in the assigned profile. Its technical key is created automatically.\n\nFor numbers, the range includes minimum and maximum in the TAG’s current unit. For booleans, choose True or False. For String or Enum, use the exact value, including case when applicable.\n\nReadings need the same source UTC time. Readings merely close in time are not enough. If the context changes in another edit, refresh the screen and review its conditions before saving.",
                    "Elija la asociación del equipo y dé al contexto un nombre que explique la condición, como Bomba encendida con caudal normal. Añada al menos una condición comprobada en un TAG del perfil asociado. La clave técnica se crea automáticamente.\n\nPara números, el intervalo incluye mínimo y máximo en la unidad actual del TAG. Para booleanos, elija Verdadero o Falso. Para String o Enum, use el valor exacto, incluidas mayúsculas cuando corresponda.\n\nLas lecturas necesitan la misma hora UTC de origen. Lecturas solo próximas no bastan. Si el contexto cambia en otra edición, actualice la pantalla y revise sus condiciones antes de guardar."),
                LS(locale, "Organize etapas do processo", "Organize process stages", "Organice etapas del proceso",
                    "Use etapas para organizar a parte do processo que deseja acompanhar, por exemplo captação, bombeamento e distribuição. Dê um nome a cada etapa, adicione associações já cadastradas e use Mover acima/abaixo para definir a ordem. Os códigos técnicos das etapas são criados pelo sistema.\n\nA ordem organiza a apresentação; não programa o acionamento dos equipamentos. Ao consultar uma etapa, cada análise continua pertencendo a um equipamento. Reunir bombas não cria um indicador conjunto nem sincroniza suas amostras.",
                    "Use stages to organize the part of the process you want to follow, such as intake, pumping and distribution. Name each stage, add existing assignments and use Move up/down to set their order. The system creates technical stage keys automatically.\n\nThe order organizes presentation; it does not program equipment actuation. When querying a stage, each analysis still belongs to one piece of Equipment. Grouping pumps does not create a combined indicator or synchronize samples.",
                    "Use etapas para organizar la parte del proceso que desea seguir, como captación, bombeo y distribución. Dé un nombre a cada etapa, añada asociaciones existentes y use Mover arriba/abajo para definir el orden. El sistema crea automáticamente las claves técnicas.\n\nEl orden organiza la presentación; no programa accionamientos. Al consultar una etapa, cada análisis sigue perteneciendo a un equipo. Reunir bombas no crea un indicador conjunto ni sincroniza sus muestras."),
                LS(locale, "Quando não há correspondência", "When there is no match", "Cuando no hay coincidencia",
                    "Confira associação, unidade, limites, valor exato e período. Depois confira se o Historian contém os TAGs e a evidência temporal exigida. Sem correspondência ou com dados insuficientes, o resultado não significa equipamento saudável, defeituoso ou eficiência zero. Preserve a razão apresentada antes de ampliar limites apenas para obter um número.",
                    "Check assignment, unit, limits, exact value and period. Then check Historian TAG coverage and required temporal evidence. No match or insufficient data does not mean healthy Equipment, faulty Equipment or zero efficiency. Understand the reported reason before widening limits merely to obtain a number.",
                    "Compruebe asignación, unidad, límites, valor exacto y período. Después cobertura Historian y evidencia temporal. Sin coincidencia o con datos insuficientes no significa equipo sano, averiado ni eficiencia cero. Entienda la causa antes de ampliar límites solo para obtener un número.")
            ], "intelligence.profiles-equipment", "intelligence.dashboard-workflow", "historian.overview", "tags.timestamps");

        yield return LT(locale, "intelligence.dashboard-workflow", "intelligence",
            Tx("Inteligência: gerar uma tela e consultar no Runtime", "Intelligence: generate a screen and query in Runtime", "Inteligencia: generar pantalla y consultar en Runtime"),
            Tx("Transforme a configuração de perfis em telas comuns que você pode editar e integrar à navegação.", "Turn profile configuration into ordinary editable screens and integrate them into navigation.", "Transforme perfiles en pantallas comunes editables e intégrelas en la navegación."),
            [
                LS(locale, "Confira os dados antes de interpretar", "Check the data before interpreting", "Revise los datos antes de interpretar",
                    "Em Engenharia > Inteligência de ativos, localize a associação do equipamento. Em Conferir dados da referência, escolha início e fim de um período conhecido e clique em Consultar referência. Os horários são locais e convertidos para UTC. Cada período pode ter até 31 dias. Leituras aceitas têm a evidência de origem exigida; rejeições explicam por que outras leituras ficaram de fora. A contagem não comprova que o equipamento estava saudável.\n\nEm Conferir condições do contexto, selecione um contexto salvo pelo nome e consulte o período. O SCADIVO usa a versão salva automaticamente. O resultado informa quantas leituras atendem a todas as condições no mesmo instante de origem. Zero leituras compatíveis pode significar condições não atendidas ou dados insuficientes; confira a explicação apresentada. Publique as alterações e ative o equipamento antes de consultar.",
                    "In Engineering > Asset intelligence, locate the equipment assignment. Under Check reference data, choose the start and end of a known period and select Query reference. Times are local and converted to UTC. Each period supports up to 31 days. Accepted readings have the required source evidence; rejections explain why other readings were excluded. Counts do not prove that the equipment was healthy.\n\nUnder Check context conditions, select a saved context by name and query the period. SCADIVO uses its saved version automatically. Results show how many readings meet all conditions at the same source time. Zero matching readings may mean unmet conditions or insufficient data; read the explanation. Publish changes and activate the equipment before querying.",
                    "En Ingeniería > Inteligencia de activos, localice la asignación del equipo. En Revisar datos de referencia, elija inicio y fin de un período conocido y pulse Consultar referencia. Las horas son locales y se convierten a UTC. Cada período admite hasta 31 días. Las lecturas aceptadas tienen la evidencia de origen exigida; los rechazos explican por qué se excluyeron otras lecturas. El conteo no demuestra que el equipo estuviera sano.\n\nEn Revisar condiciones del contexto, seleccione un contexto guardado por su nombre y consulte el período. SCADIVO usa su versión guardada automáticamente. El resultado indica cuántas lecturas cumplen todas las condiciones en el mismo instante de origen. Cero lecturas compatibles puede indicar condiciones no cumplidas o datos insuficientes; lea la explicación. Publique los cambios y active el equipo antes de consultar."),
                LS(locale, "Entenda as contagens e as condições", "Understand counts and conditions", "Entienda los conteos y las condiciones",
                    "As análises são consultadas sob demanda: editar perfis ou ativar um escopo não inicia análise contínua. Na referência, leia os motivos ao lado de Não disponível. Um sinal obrigatório de texto, opção ou verdadeiro/falso não entra na coorte numérica obrigatória; a contagem dos sinais numéricos do perfil continua sendo apresentada separadamente. Contagem zero de um tipo não consultado não prova ausência de histórico.\n\nNa consulta de contexto, veja primeiro Condições do contexto: leituras aceitas e quantas atenderam a cada condição. Uma condição de modo pode ser textual e ainda selecionar os instantes válidos para corrente ou vazão. Depois confira as medições nas condições selecionadas. Essas contagens não comprovam saúde ou eficiência.",
                    "Analyses are queried on demand: editing profiles or activating a scope does not start continuous analysis. In reference evidence, read the reasons beside Unavailable. A required text, enum or Boolean signal is outside the required numeric cohort; numeric profile counts are shown separately. A zero count for an unqueried type does not prove there is no history.\n\nIn context queries, start with Context conditions: accepted readings and how many matched each condition. A textual operating mode can still select valid timestamps for current or flow. Then review measurements under the selected conditions. These counts do not prove health or efficiency.",
                    "Los análisis se consultan bajo demanda: editar perfiles o activar un alcance no inicia análisis continuo. En la referencia, lea los motivos junto a No disponible. Una señal obligatoria de texto, opción o verdadero/falso no entra en la cohorte numérica obligatoria; los conteos numéricos del perfil se muestran por separado. Un conteo cero de un tipo no consultado no demuestra ausencia de histórico.\n\nEn las consultas de contexto, revise primero Condiciones del contexto: lecturas aceptadas y cuántas cumplieron cada condición. Un modo textual puede seleccionar instantes válidos de corriente o caudal. Después revise las mediciones en las condiciones seleccionadas. Estos conteos no demuestran salud ni eficiencia."),
                LS(locale, "Compare dois períodos e cancele consultas", "Compare two periods and cancel queries", "Compare dos períodos y cancele consultas",
                    "Nas consultas de referência e condições do contexto, marque Comparar com outro período se quiser conferir a evidência em duas janelas. Preencha o início e o fim da comparação. Cada janela pode ter até 31 dias, e o início da comparação deve ser estritamente posterior ao fim da referência: não use o mesmo instante nos dois limites. A consulta fica indisponível enquanto houver campos vazios, período invertido ou sobreposição.\n\nConsulte e leia as contagens de cada período. A comparação de contagens não é, por si só, um indicador de eficiência. Desmarcar a comparação ou alterar qualquer limite remove o resultado anterior. Durante a leitura, use Cancelar consulta: uma resposta atrasada não deve reaparecer na tela. Para consultar novamente, confira os parâmetros e clique no botão de consulta.",
                    "In reference and context-condition queries, select Compare with another period to inspect evidence in two windows. Enter comparison start and end. Each window supports up to 31 days, and comparison must start strictly after the reference ends: do not use the same instant for both boundaries. Querying remains unavailable while fields are empty, dates are reversed or periods overlap.\n\nQuery and read each period's counts. Comparing counts is not, by itself, an efficiency indicator. Disabling comparison or changing any boundary clears the previous result. During reading, use Cancel query: a delayed response must not reappear. To query again, review the parameters and select the query button.",
                    "En las consultas de referencia y condiciones del contexto, marque Comparar con otro período para revisar evidencia en dos ventanas. Indique inicio y fin de la comparación. Cada ventana admite hasta 31 días, y la comparación debe comenzar estrictamente después del fin de referencia: no use el mismo instante en ambos límites. La consulta permanece deshabilitada con campos vacíos, fechas invertidas o superposición.\n\nConsulte y lea los conteos de cada período. Comparar conteos no es, por sí solo, un indicador de eficiencia. Desmarcar la comparación o cambiar cualquier límite elimina el resultado anterior. Durante la lectura, use Cancelar consulta: una respuesta tardía no debe reaparecer. Para consultar de nuevo, revise los parámetros y pulse el botón de consulta."),
                LS(locale, "Use o desvio conjunto experimental", "Use experimental joint deviation", "Use la desviación conjunta experimental",
                    "Abra Desvio conjunto experimental na associação. Escolha o contexto salvo e de duas a oito medições numéricas; medições que definem as condições do contexto ficam fora da lista de alvos. Informe o intervalo real de aquisição em segundos, de 1 a 86.400. Não invente esse valor: ele descreve a frequência esperada das leituras. Escolha uma referência e um período posterior de avaliação, sem sobreposição, e clique em Calcular desvio conjunto.\n\nO resultado mostra quantos instantes puderam ser avaliados e quantos ficaram em aquecimento. O desvio combina mudanças de nível e da relação entre sinais. Expanda Contribuições das medições para investigar a participação de cada sinal. Esses números não têm unidade física e não diagnosticam causa, falha ou vida útil. A função é experimental, validada somente por simulação e sem limiar de alarme validado em campo.\n\nUse Cancelar consulta para interromper. Mudar período, contexto, sinais ou cadência descarta o resultado anterior; é preciso consultar novamente. Se a referência não puder ser ajustada, confira dados, qualidade, sincronização, contexto e variação dos sinais antes de ampliar períodos.",
                    "Open Experimental joint deviation in the assignment. Choose the saved context and two to eight numeric measurements; measurements defining context conditions are excluded from target choices. Enter the actual acquisition interval in seconds, from 1 to 86,400. Do not invent this value: it describes the expected reading frequency. Choose a reference and a later, non-overlapping evaluation period, then select Calculate joint deviation.\n\nResults show scored timestamps and warmup counts. Deviation combines changes in level and relationships between signals. Expand Measurement contributions to investigate each signal's contribution. These numbers have no physical unit and do not diagnose causes, faults or remaining life. This experimental function is validated by simulation only and has no field-validated alarm threshold.\n\nUse Cancel query to stop. Changing periods, context, signals or cadence discards previous results; query again. If the reference cannot be fitted, check data, quality, synchronization, context and signal variation before widening periods.",
                    "Abra Desviación conjunta experimental en la asignación. Elija el contexto guardado y de dos a ocho mediciones numéricas; las mediciones que definen las condiciones del contexto se excluyen de los objetivos. Indique el intervalo real de adquisición en segundos, de 1 a 86.400. No invente ese valor: describe la frecuencia esperada de las lecturas. Elija una referencia y un período posterior de evaluación sin superposición, y pulse Calcular desviación conjunta.\n\nEl resultado muestra instantes evaluados y en calentamiento. La desviación combina cambios de nivel y de la relación entre señales. Expanda Contribuciones de las mediciones para investigar la participación de cada señal. Los números no tienen unidad física ni diagnostican causas, fallos o vida útil. La función es experimental, validada solo por simulación y sin umbral de alarma validado en campo.\n\nUse Cancelar consulta para interrumpir. Cambiar períodos, contexto, señales o cadencia descarta el resultado anterior; consulte de nuevo. Si no se puede ajustar la referencia, revise datos, calidad, sincronización, contexto y variación de señales antes de ampliar períodos."),
                LS(locale, "Escolha o que a tela vai responder", "Choose the question the screen will answer", "Elija qué responderá la pantalla",
                    "Escolha primeiro a pergunta que a tela vai ajudar a responder. Valores e tendências mostram os sinais. Cobertura mostra se há dados utilizáveis. Desempenho aplica uma regra de cálculo. Desvio contextual compara sinais dentro das condições selecionadas.\n\nUse um perfil ou etapa já completo. Algumas opções pedem uma regra de desempenho e sinais/faixas de contexto antes de gerar. Selecione os TAGs do perfil e associação corretos. Nomes parecidos em equipamentos diferentes não tornam os recursos intercambiáveis.",
                    "First choose the question the screen will help answer. Values and trends show signals. Coverage shows whether usable data exists. Performance applies a calculation rule. Contextual deviation compares signals within selected conditions.\n\nUse a complete profile or stage. Some options require a performance rule and context signals/ranges before generation. Select TAGs from the correct profile and assignment. Similar names in different equipment do not make resources interchangeable.",
                    "Elija primero la pregunta que ayudará a responder la pantalla. Valores y tendencias muestran señales. Cobertura indica si hay datos utilizables. Rendimiento aplica una regla de cálculo. Desviación contextual compara señales en las condiciones elegidas.\n\nUse un perfil o etapa completos. Algunas opciones requieren regla de rendimiento y señales/intervalos de contexto antes de generar. Elija TAGs del perfil y asociación correctos. Nombres similares en equipos distintos no hacen intercambiables sus recursos."),
                LS(locale, "Componha os objetos e as vistas", "Compose objects and views", "Componga objetos y vistas",
                    "Depois de escolher a origem, abra cada medição em Objetos de medição. Escolha valor numérico, gauge semicircular, anel, barra, régua vertical, faixas ou valor com meta. Confira o tema e a unidade. Objetos com escala precisam de mínimo e máximo válidos; o cadastro do TAG pode preenchê-los. Faixas exigem dois limites ordenados dentro da escala e a meta precisa estar dentro dos limites. Não invente esses valores para liberar a geração. Sem escala conhecida, use Valor numérico.\n\nEm Conteúdo analítico do painel, inclua cada análise configurada que deseja mostrar. Desempenho e desvio contextual são independentes. O link Configurar análises da associação leva aos controles de regras e sinais existentes. Quando há várias vistas, elas recebem botões de navegação. A geração não executa as consultas.\n\nPara uma etapa, o mesmo gerador oferece Cobertura por equipamento e Análises por equipamento. A lista mostra o que já está configurado em cada membro. Use Configurar este equipamento para escolher as regras e sinais que faltam; depois volte ao gerador. Não é necessário configurar desvio em todos para gerar desempenho nos demais. As vistas selecionadas são Telas vinculadas e editáveis. No Runtime, escolha o equipamento e a análise, informe o período e consulte. Cada resultado continua pertencendo somente ao equipamento escolhido.\n\nPara conferir uma referência no Runtime, escolha um perfil de equipamento no gerador e marque Conferir dados da referência. A opção acrescenta uma Tela própria; não depende de configurar desempenho ou desvio. Aplique o conjunto, salve, publique e ative. No Runtime ao vivo, abra Dados da referência, escolha um período conhecido e selecione Consultar referência. Você verá leituras recebidas, aceitas e rejeitadas por sinal e quantas puderam ser usadas juntas. Se quiser comparar outro período, marque Comparar com outro período e informe um intervalo posterior, sem sobreposição. Uma contagem alta não comprova que o equipamento estava saudável. Mudar os períodos limpa o resultado. Editor e reprodução histórica não executam esta consulta.\n\nPara consultar referências dos equipamentos de uma etapa, escolha a etapa no gerador e marque Dados da referência por equipamento. Não é necessário configurar desempenho ou desvio. A opção usa a mesma Tela de análises da etapa; o conjunto continua com até três Telas. No Runtime, abra Análises por equipamento, escolha o equipamento e selecione Dados da referência. Informe os períodos e consulte. Ao escolher outro equipamento, o relatório anterior é fechado, a consulta em andamento é cancelada e o resultado é limpo; nada é consultado automaticamente para o novo equipamento.\n\nPara levar as condições de operação ao Runtime, primeiro salve um contexto na associação do equipamento. No gerador, escolha esse perfil e marque Condições de operação. A opção acrescenta uma Tela própria e funciona sem desempenho ou desvio configurados. Aplique o conjunto, salve, publique e ative. No Runtime ao vivo, abra Condições de operação, escolha Contexto salvo pelo nome, informe o início e o fim do período e clique em Consultar condições. Para comparar, use outro período posterior, sem sobreposição. O resultado mostra quantas leituras atendem a cada condição e quantas atendem a todas ao mesmo tempo. Por exemplo, uma condição de pressão entre 0 e 200 kPa pode selecionar leituras que uma faixa de 0 a 50 kPa exclui. Zero leituras compatíveis não significa equipamento saudável: significa que o período não fornece dados nas condições escolhidas. Trocar o contexto ou os períodos limpa o resultado anterior. Se o contexto mudar na Engenharia, gere e publique novamente a vista; ela não assume silenciosamente uma nova versão. Editor e reprodução histórica não executam a consulta. Esta opção está disponível por perfil de equipamento; a vista de condições nos membros de etapas ainda está pendente.",
                    "After choosing the source, open each measurement under Measurement objects. Choose numeric value, semicircular dial, ring, bar, vertical ruler, bands or value with a target. Check theme and unit. Scaled objects need valid minimum and maximum limits; TAG settings may prefill them. Bands require ordered boundaries inside the scale, and targets must be within its limits. Do not invent values to enable generation. Use Numeric value when no scale is known.\n\nUnder Dashboard analyses, include each configured analysis you want to show. Performance and contextual deviation are independent. Configure assignment analyses links to the existing rule and signal controls. Multiple generated views receive navigation buttons. Generation does not execute queries.\n\nFor a stage, the same generator offers Member coverage and Member analyses. The list shows what is configured for each member. Use Configure this equipment to choose missing rules and signals, then return to the generator. Deviation does not need to be configured for every member to generate performance for the others. Selected views are linked, editable Screens. In Runtime, choose the equipment and analysis, set the period and query. Each result still belongs only to the selected equipment.\n\nTo check a reference in Runtime, choose an equipment profile in the generator and select Check reference data. This adds a separate Screen; it does not require performance or deviation configuration. Apply the set, save, publish and activate. In live Runtime, open Reference data, choose a known period and select Query reference. You will see received, accepted and rejected readings for each signal and how many could be used together. To compare another period, select Compare with another period and enter a later, non-overlapping interval. A high count does not prove the equipment was healthy. Changing the periods clears the result. The editor and historical playback do not execute this query.\n\nTo check reference data for stage equipment, choose the stage in the generator and select Reference data per equipment. Performance or deviation configuration is not required. This uses the same stage analyses Screen, keeping the set to at most three Screens. In Runtime, open Member analyses, choose the equipment and select Reference data. Enter the periods and query. Choosing another equipment closes the previous report, cancels a pending query and clears its result; no query runs automatically for the new equipment.\n\nTo bring operating conditions into Runtime, first save a context in the equipment assignment. In the generator, choose that profile and select Operating conditions. This adds a separate Screen and works without configured performance or deviation. Apply the set, save, publish and activate. In live Runtime, open Operating conditions, choose Saved context by name, enter the period start and end, and select Query conditions. To compare, use a later, non-overlapping period. The result shows how many readings meet each condition and how many meet all conditions together. For example, a pressure condition from 0 to 200 kPa may select readings that a range from 0 to 50 kPa excludes. Zero matching readings does not mean healthy equipment: it means the period provides no data under the selected conditions. Changing the context or periods clears the previous result. If the context changes in Engineering, generate and publish the view again; it does not silently assume a new version. The editor and historical playback do not execute the query. This option is available per equipment profile; the conditions view for stage members is still pending.",
                    "Después de elegir la fuente, abra cada medición en Objetos de medición. Elija valor numérico, dial semicircular, anillo, barra, regla vertical, intervalos o valor con meta. Compruebe tema y unidad. Los objetos con escala necesitan mínimo y máximo válidos; pueden venir del TAG. Los intervalos requieren límites ordenados dentro de la escala y la meta debe estar dentro de sus límites. No invente valores para habilitar la generación. Sin escala conocida, use Valor numérico.\n\nEn Análisis del panel, incluya cada análisis configurado que desea mostrar. Rendimiento y desviación contextual son independientes. Configurar análisis de la asignación lleva a los controles existentes de reglas y señales. Las vistas generadas reciben botones de navegación. La generación no ejecuta consultas.\n\nPara una etapa, el mismo generador ofrece Cobertura por equipo y Análisis por equipo. La lista muestra qué tiene configurado cada miembro. Use Configurar este equipo para elegir reglas y señales pendientes y vuelva al generador. No necesita configurar desviación en todos para generar rendimiento en los demás. Las vistas elegidas son Pantallas vinculadas y editables. En Runtime, elija el equipo y el análisis, indique el período y consulte. Cada resultado pertenece solo al equipo elegido.\n\nPara revisar una referencia en Runtime, elija un perfil de equipo en el generador y marque Revisar datos de referencia. Agrega una Pantalla propia; no requiere configurar rendimiento o desviación. Aplique el conjunto, guarde, publique y active. En Runtime en vivo, abra Datos de referencia, elija un período conocido y seleccione Consultar referencia. Verá lecturas recibidas, aceptadas y rechazadas por señal y cuántas se pudieron usar juntas. Para comparar otro período, marque Comparar con otro período e indique un intervalo posterior sin solapamiento. Un número alto no demuestra que el equipo estuviera sano. Cambiar los períodos borra el resultado. El editor y la reproducción histórica no ejecutan esta consulta.\n\nPara consultar referencias de los equipos de una etapa, elija la etapa en el generador y marque Datos de referencia por equipo. No necesita configurar rendimiento o desviación. Usa la misma Pantalla de análisis de etapa; el conjunto sigue teniendo hasta tres Pantallas. En Runtime, abra Análisis por equipo, elija el equipo y seleccione Datos de referencia. Indique los períodos y consulte. Elegir otro equipo cierra el informe anterior, cancela una consulta pendiente y borra su resultado; no se consulta automáticamente el nuevo equipo.\n\nPara llevar las condiciones de operación al Runtime, primero guarde un contexto en la asignación del equipo. En el generador, elija ese perfil y marque Condiciones de operación. Añade una Pantalla propia y funciona sin rendimiento o desviación configurados. Aplique el conjunto, guarde, publique y active. En Runtime en vivo, abra Condiciones de operación, elija Contexto guardado por nombre, indique inicio y fin del período y seleccione Consultar condiciones. Para comparar, use un período posterior sin solapamiento. El resultado muestra cuántas lecturas cumplen cada condición y cuántas cumplen todas a la vez. Por ejemplo, una condición de presión entre 0 y 200 kPa puede seleccionar lecturas que un intervalo de 0 a 50 kPa excluye. Cero lecturas compatibles no significa equipo sano: significa que el período no proporciona datos en las condiciones elegidas. Cambiar el contexto o los períodos borra el resultado anterior. Si el contexto cambia en Ingeniería, genere y publique de nuevo la vista; no asume una nueva versión silenciosamente. El editor y la reproducción histórica no ejecutan la consulta. Está disponible por perfil de equipo; la vista de condiciones para miembros de etapas sigue pendiente."),
                LS(locale, "Gere e finalize o rascunho", "Generate and finish the draft", "Genere y termine el borrador",
                    "1. Salve a configuração de perfis, associações e etapas.\n2. Na parte superior da página de Inteligência, abra Gerar painel para o Runtime e escolha um perfil de equipamento ou uma etapa. O rascunho básico precisa de ao menos um TAG numérico resolvido.\n3. Use Gerar rascunho do painel. O SCADIVO abre uma Tela comum no editor; ela ainda não foi salva.\n4. Confira título, unidades, tamanho, leitura e vínculos dos objetos. Quando o gerador produzir Telas vinculadas, Pré-visualizar e Aplicar ao Workspace incluem o conjunto inteiro, para preservar os destinos da navegação. Revise o conjunto antes de aplicar.\n5. Salve, publique e ative a revisão do projeto. Configure ou confira a navegação e abra a Tela no Runtime.\n\nSe a configuração da Intelligence tiver alterações não salvas, salve-a primeiro. Licença e permissões também precisam estar válidas. O gerador básico organiza TAGs existentes em cartões de valor, tendência e cobertura; não consulta valores atuais nem Historian e não inventa KPI. Ele não salva nem ativa a Tela automaticamente. O painel usa um fundo escuro próprio para manter o contraste nos temas claro e escuro; você pode alterá-lo em Fundo no editor, conferindo também as cores dos textos e valores. Ações guiadas especializadas podem pedir uma regra de desempenho e sinais/faixas de contexto.",
                    "1. Save the profiles, assignments and process stages.\n2. At the top of the Asset & Process Intelligence page, open Create a Runtime dashboard and choose an equipment profile or process stage. The basic draft needs at least one resolved numeric TAG.\n3. Select Generate dashboard draft. SCADIVO opens a normal Screen in the editor; it has not been saved yet.\n4. Check its title, units, size, readability and object bindings. When the generator creates linked Screens, Preview and Apply to Workspace include the whole set to preserve navigation destinations. Review the set before applying.\n5. Save, publish and activate the project revision. Set up or check navigation, then open the Screen in Runtime.\n\nSave any unsaved Intelligence configuration first. The license and permissions must also be valid. The basic generator arranges existing TAGs into value cards, a trend and coverage; it does not query current values or Historian and does not invent KPIs. It does not save or activate the Screen automatically. Its own dark background retains contrast under either application theme; you can change it under Background in the editor, checking text and value colors too. Specialized guided actions may ask for a performance rule and context signals/ranges.",
                    "1. Guarde los perfiles, las asignaciones y las etapas del proceso.\n2. En la parte superior de la página de Inteligencia de activos, abra Crear un panel para Runtime y elija un perfil de equipo o una etapa. El borrador básico necesita al menos un TAG numérico resuelto.\n3. Pulse Generar borrador del panel. SCADIVO abre una Pantalla normal en el editor; todavía no está guardada.\n4. Revise título, unidades, tamaño, lectura y vínculos de los objetos. Si el generador crea Pantallas vinculadas, Preview y Aplicar al Workspace incluyen el conjunto completo para conservar los destinos de navegación. Revise el conjunto antes de aplicar.\n5. Guarde, publique y active la revisión del proyecto. Configure o compruebe la navegación y abra la Pantalla en Runtime.\n\nGuarde primero los cambios de Intelligence que sigan pendientes. La licencia y los permisos también deben estar vigentes. El generador básico organiza TAGs existentes en tarjetas de valor, una tendencia y cobertura; no consulta valores actuales ni Historian y no inventa KPI. No guarda ni activa la Pantalla automáticamente. Su fondo oscuro conserva el contraste en ambos temas del sistema; puede cambiarlo en Fondo en el editor, comprobando también los colores de textos y valores. Las acciones guiadas especializadas pueden pedir una regla de rendimiento y señales/intervalos de contexto."),
                LS(locale, "Consulte e interprete com o contexto visível", "Query and interpret with context visible", "Consulte e interprete con contexto visible",
                    "No Runtime, escolha equipamento, análise e período e solicite a consulta. Junto do número, confira qual equipamento, revisão, unidade e avisos aparecem na resposta. Isso evita comparar resultados de situações diferentes.\n\nNa tela de membros de etapa, desempenho e desvio têm solicitações independentes. Os resultados são temporários; mudar de equipamento limpa o anterior. Use os resultados e suas limitações para orientar a investigação. Eles não são diagnóstico de manutenção nem comprovação de eficiência em campo.",
                    "In Runtime, choose equipment, analysis and period and request the query. Alongside the number, check equipment identity, revision, unit and warnings in the response. This avoids comparing results from different situations.\n\nIn stage-member screens, performance and deviation use independent requests. Results are temporary; changing equipment clears the previous one. Use results and their limits to guide investigation. They are not maintenance diagnoses or proof of field efficiency.",
                    "En Runtime, elija equipo, análisis y período y solicite la consulta. Junto al número compruebe equipo, revisión, unidad y avisos de la respuesta. Evita comparar situaciones distintas.\n\nEn pantallas de miembros de etapa, rendimiento y desviación tienen solicitudes independientes. Los resultados son temporales; cambiar equipo borra el anterior. Use resultados y limitaciones para orientar la investigación. No son diagnóstico de mantenimiento ni prueba de eficiencia en campo.")
            ], "intelligence.profiles-equipment", "intelligence.operating-contexts", "intelligence.process-stage-member-insights", "visual.first-screen", "engineering.lifecycle");
    }
}
